        SetAbilityState(battler, ability, TRUE);

        gQueuedExtraAttackData[++gQueuedAttackCount] = (struct ExtraAttackActionStruct){
            .ability = ability,
            .move = MOVE_ACID,
            .movePower = 20,
            .attacker = (u8)battler,
            .target = (u8)BATTLE_OPPOSITE(battler),
        };

        return TRUE;
    }

