        type2 = gBattleMons[target].type2;
        type3 = gBattleMons[target].type3;

        if (type1 == TYPE_GHOST) {
            if (type1 == type2) {
                if (type3 == TYPE_GHOST) {
                    gBattleMons[target].type1 = gBattleMons[target].type2 = gBattleMons[target].type3 = TYPE_MYSTERY;
